from AlgorithmImports import *
from datetime import datetime, date, time, timedelta
from collections import defaultdict


class SpyBullishOptionStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe
                         .IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(0, 365))
        self.option = option

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.minute_buckets = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_liquidation_day = None
        self.expiration_processed_day = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_option is not None:
            security = self.Securities[self.held_option]
            expiration = security.Symbol.ID.Date.date()

            if current_date >= expiration:
                if self.expiration_processed_day != current_date:
                    self.Debug("Unexpected option position at expiration; liquidating.")
                    self._liquidate_option("expiration")
                    self.expiration_processed_day = current_date
            elif (current_date == expiration - timedelta(days=1)
                  and self.Time.time() >= time(15, 45)):
                if self.expiration_liquidation_day != current_date:
                    self.Debug("Time-stop exit submitted.")
                    self._liquidate_option("time stop")
                    self.expiration_liquidation_day = current_date
            else:
                self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        bucket_start_minute = 30 + ((end.minute - 31) // 5) * 5
        bucket_start = datetime.combine(end.date(), time(9, 30)) + timedelta(
            minutes=bucket_start_minute - 30
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        bucket = self.minute_buckets.get(bucket_start)
        if bucket is None:
            bucket = {
                "bars": {},
                "invalid": False,
                "end": bucket_end
            }
            self.minute_buckets[bucket_start] = bucket

        expected_minute = bucket_start + timedelta(
            minutes=len(bucket["bars"]) + 1
        )

        if end != expected_minute:
            bucket["invalid"] = True

        bucket["bars"][end] = bar

        if end != bucket_end:
            return

        completed = self.minute_buckets.pop(bucket_start)

        if completed["invalid"] or len(completed["bars"]) != 5:
            return

        ordered_bars = sorted(completed["bars"].values(), key=lambda x: x.EndTime)
        five_minute_close = ordered_bars[-1].Close
        self._process_five_minute_close(
            five_minute_close, bucket_end, slice
        )

    def _process_five_minute_close(self, close, bar_end, slice):
        self.closes.append(float(close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if (bullish
                and time(9, 45) <= bar_end.time() <= time(14, 30)):
            self._evaluate_entry(slice)

    def _evaluate_entry(self, slice: Slice):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chains = slice.OptionChains
        chain = chains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiration = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Entry skipped: no qualifying expiration.")
            return

        selected_expiration = expirations[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying contract.")
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.entry_price is None or self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.held_option),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("profit target")

    def _liquidate_option(self, reason):
        if self.held_option is None or self.exit_ticket is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.entry_ticket.OrderId)

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option, -quantity
            )
            self.Debug("Exit submitted: " + reason)

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment; liquidating.")
            self.MarketOrder(
                self.spy, -self.Portfolio[self.spy].Quantity
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.exit_ticket = None
                    self.Debug(
                        "Entry filled: {} at {}".format(
                            self.held_option, self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Option exit filled.")
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None
