from AlgorithmImports import *
from datetime import timedelta


class SpyOptionMovingAverageAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.signal_bar_end = None
        self.prevent_entry_today = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.EndTime.time() < time(9, 35) or bar.EndTime.time() > time(16, 0):
            return

        previous_fast = None
        previous_slow = None

        if self.fast_window.IsReady:
            previous_fast = sum(self.fast_window) / 5.0
        if self.slow_window.IsReady:
            previous_slow = sum(self.slow_window) / 20.0

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        if (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            end_time = bar.EndTime.time()
            if time(9, 45) <= end_time <= time(14, 30):
                self.signal_bar_end = bar.EndTime

    def OnData(self, slice):
        today = self.Time.date()

        if self.prevent_entry_today and today != getattr(self, "_prevented_date", None):
            self.prevent_entry_today = False

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(today)

        if self.held_symbol is not None:
            self._evaluate_open_position(slice, today)

        if self.signal_bar_end is not None:
            signal_time = self.signal_bar_end
            self.signal_bar_end = None
            self._try_enter(slice, signal_time.date())

    def _try_enter(self, slice, signal_date):
        if self.prevent_entry_today:
            return
        if self.held_symbol is not None or self._entry_order_open():
            return
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_price = self.Securities[self.spy_symbol].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Symbol.ID.Symbol == "SPY"
                    and contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible expiration or contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * current_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no eligible strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_open_position(self, slice, today):
        if self.held_symbol not in slice.OptionChains:
            quote = None
        else:
            chain = slice.OptionChains[self.held_symbol]
            quote = chain.Contracts.get(self.held_symbol)

        if (
            quote is not None
            and quote.BidPrice > 0
            and quote.AskPrice > 0
            and self.entry_price is not None
        ):
            midpoint = (quote.BidPrice + quote.AskPrice) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("profit target")
                return

        if (
            self.time_stop_date is not None
            and today == self.time_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration_processing(self, today):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if today >= self.expiration_date:
            self.prevent_entry_today = True
            self._prevented_date = today
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        if self.entry_ticket is not None and self._entry_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None:
            self.entry_ticket = None

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.prevent_entry_today = True
            self._prevented_date = self.Time.date()
            self.Liquidate(self.spy_symbol)
            self.Debug("Unexpected exercise or assignment: SPY equity liquidated.")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.expiration_date = self.Securities[
                self.held_symbol
            ].Symbol.ID.Date.date()

            self.time_stop_date = self._previous_trading_day(self.expiration_date)
            self.Debug(
                f"Entry filled: {self.held_symbol}, price={self.entry_price:.4f}"
            )
            self.entry_ticket = None

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(f"Exit filled: {order_event.Symbol}")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.expiration_date = None
            self.time_stop_date = None

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate


