from AlgorithmImports import *
from datetime import timedelta, time


class SpyOptionMovingAverageAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.previous_bar_end = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()

        if self.held_option is None:
            return

        if self.entry_ticket is not None and not self.IsOrderClosed(self.entry_ticket):
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        local_time = self.Time.time()

        if self.IsTimeStopDue(local_time):
            self.SubmitExit("scheduled time stop")
            return

        contract = self.GetCurrentOptionContract(slice, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50% profit target")

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        local_end = bar.EndTime.astimezone(self.TimeZone).time()
        local_date = bar.EndTime.astimezone(self.TimeZone).date()

        if local_end < time(9, 35) or local_end > time(16, 0):
            return

        if self.previous_bar_end is not None:
            previous_local_end = self.previous_bar_end.astimezone(
                self.TimeZone
            )
            if previous_local_end.date() == local_date:
                if bar.EndTime - self.previous_bar_end != timedelta(minutes=5):
                    self.previous_bar_end = bar.EndTime
                    return

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)
        self.previous_bar_end = bar.EndTime

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        eligible = (
            time(9, 45) <= local_end <= time(14, 30)
        )
        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible and bullish_cross:
            self.TryEnterOption(local_date)

    def TryEnterOption(self, algorithm_date):
        if self.current_slice is None:
            self.Debug("Skipped entry: current Slice unavailable.")
            return

        if self.blocked_entry_date == algorithm_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.IsOrderClosed(self.entry_ticket):
            return

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        chains = list(self.current_slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                symbol = contract.Symbol
                if (
                    symbol.SecurityType == SecurityType.Option
                    and symbol.ID.OptionStyle == OptionStyle.American
                    and symbol.ID.OptionRight == OptionRight.Call
                    and symbol.ID.Date.date() >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = min(
            contract.Symbol.ID.Date.date() for contract in candidates
        )
        strike_floor = spy_price * 1.01

        strike_candidates = [
            contract for contract in candidates
            if contract.Symbol.ID.Date.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying contract at expiration.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiration={selected.Symbol.ID.Date.date()} "
            f"strike={selected.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} "
                    f"price={order_event.FillPrice}"
                )
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"Exit filled: {order_event.Symbol} "
                f"price={order_event.FillPrice}"
            )
            if not self.Portfolio[order_event.Symbol].Invested:
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
            return

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"{order_event.Symbol}"
            )
            self.HandleUnexpectedEquityPosition()

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.IsOrderClosed(self.exit_ticket):
            return

        if self.entry_ticket is not None and not self.IsOrderClosed(self.entry_ticket):
            return

        self.exit_ticket = self.Liquidate(self.held_option)
        self.Debug(f"Exit submitted: {self.held_option} reason={reason}")

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def IsTimeStopDue(self, local_time):
        if self.held_option is None:
            return False

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == previous_trading_day
            and local_time >= time(15, 45)
        )

    def HandleUnexpectedEquityPosition(self):
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity
            )

    def GetCurrentOptionContract(self, slice, symbol):
        for chain in slice.OptionChains:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def IsOrderClosed(self, ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        )

