        local_end = bar.EndTime.astimezone(self.TimeZone).time()
        local_date = bar.EndTime.astimezone(self.TimeZone).date()

        if local_end < time(9, 35) or local_end > time(16, 0):
            return

        if self.previous_bar_end is not None:
            previous_local_end = self.previous_bar_end.astimezone(
                self.TimeZone
            )
            if previous_local_end.date() == local_date:
