        self.expiration_liquidation_date = None
        self.no_replacement_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self._has_spy_equity_position():
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position detected; liquidating."
            )
            self.Liquidate(self.spy.Symbol, "Unexpected exercise or assignment")
            self.no_replacement_date = current_date

        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if current_date >= expiration_date:
                self._liquidate_option(
                    "Expiration processing: liquidating remaining option position"
                )
                self.no_replacement_date = current_date
            else:
                if self.stop_date is None:
                    self.stop_date = self._previous_trading_day(expiration_date)

                if (
                    current_date == self.stop_date
                    and self.Time.time() >= time(15, 45)
                ):
                    self._liquidate_option("Expiration-preceding-day time stop")
                else:
                    self._evaluate_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        bucket_minute = ((end_time.minute + 4) // 5) * 5
        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            end_time.hour,
            0,
            0
        ) + timedelta(minutes=bucket_minute)

        if (
            self.current_bucket_end is not None
            and (
                bucket_end != self.current_bucket_end
                or local_date != self.current_bucket_date
            )
        ):
            self._complete_bucket(slice)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_date = local_date
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = []

        self.current_bucket_bars.append(bar)

        if end_time.time() == time(16, 0):
            self._complete_bucket(slice)

    def _complete_bucket(self, slice: Slice):
        if self.current_bucket_end is None:
            return

        bars = sorted(self.current_bucket_bars, key=lambda x: x.EndTime)
        valid = len(bars) == 5

        if valid:
            expected = bars[0].EndTime
            for item in bars:
                if item.EndTime != expected:
                    valid = False
                    break
                expected += timedelta(minutes=1)

        if valid:
            close = bars[-1].Close
            previous_fast = (
                self.fast_window[0] if self.fast_window.Count >= 5 else None
            )
            previous_slow = (
                self.slow_window[0] if self.slow_window.Count >= 20 else None
            )

            self.fast_window.Add(close)
            self.slow_window.Add(close)

            if (
                previous_fast is not None
                and previous_slow is not None
                and self.fast_window.IsReady
                and self.slow_window.IsReady
            ):
                current_fast = sum(
                    self.fast_window[i] for i in range(5)
                ) / 5.0
                current_slow = sum(
                    self.slow_window[i] for i in range(20)
                ) / 20.0

                crossover_time = self.current_bucket_end.time()
                eligible_time = (
                    time(9, 45) <= crossover_time <= time(14, 30)
                )

                bullish = (
                    previous_fast <= previous_slow
                    and current_fast > current_slow
                )

                if bullish and eligible_time:
                    self._try_enter(slice)

