        self.current_bucket_end = None
        self.current_bucket_bars = []

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_replacement_date == current_date:
            return

        if self.held_option is not None or self.entry_ticket is not None:
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol.Underlying == self.spy.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug(f"{self.Time}: Skipped entry; no option chain.")
            return

        minimum_expiration = current_date + timedelta(days=7)
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right in (OptionRight.Call, OptionRight.Put)
                and contract.Expiry.date() >= minimum_expiration
            }
        )

        if not expirations:
            self.Debug(f"{self.Time}: Skipped entry; no eligible expiration.")
            return

        selected_expiration = expirations[0]
        target_strike = 1.01 * float(self.Securities[self.spy.Symbol].Price)

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= target_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped entry; no eligible contract at "
                f"{selected_expiration}."
            )
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _liquidate_option(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None:
            self.entry_ticket.Cancel("Position exit requested")
            self.entry_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"{self.Time}: {reason} for {self.held_option}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.stop_date = self._previous_trading_day(
                    self.held_option.ID.Date.date()
                )
                self.Debug(
                    f"{self.Time}: Entered {self.held_option} at "
                    f"{self.entry_price:.4f}."
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exited {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.4f}."
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_order_event: OrderEvent):
        self.Debug(
            f"{self.Time}: Unexpected exercise or assignment processed."
        )
        if self._has_spy_equity_position():
            self.Liquidate(self.spy.Symbol, "Exercise or assignment handling")
        self.no_replacement_date = self.Time.date()

    def _has_spy_equity_position(self):
        return self.Portfolio[self.spy.Symbol].Quantity != 0

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

