        if self.blocked_entry_date == current_date:
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        eligible_expirations = []
        minimum_expiration = current_date + timedelta(days=7)

        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiration_date = contract.Expiry.date()
                if expiration_date >= minimum_expiration:
                    eligible_expirations.append(expiration_date)

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiration = min(eligible_expirations)
