        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_end = TimeZoneInfo.ConvertTimeBySystemTimeZoneId(
            bar.EndTime, "America/New_York"
        )

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        if local_end.time().minute % 5 != 0:
            return

        end_time = local_end.replace(second=0, microsecond=0)
        start_time = end_time - timedelta(minutes=5)

        required_times = [
            start_time + timedelta(minutes=i) for i in range(5)
        ]

        self._minute_bars[end_time] = bar

        bars = []
        for minute_time in required_times:
            minute_bar = self._minute_bars.get(minute_time)
            if minute_bar is None:
                return
            bars.append(minute_bar)

        for key in list(self._minute_bars):
            if key <= end_time - timedelta(minutes=10):
                del self._minute_bars[key]

        close = bars[-1].Close
        self._fast_values.append(close)
        self._slow_values.append(close)

        if len(self._fast_values) > 5:
            self._fast_values.pop(0)
        if len(self._slow_values) > 20:
            self._slow_values.pop(0)

        if len(self._fast_values) < 5 or len(self._slow_values) < 20:
            return

        previous_fast = self._fast
        previous_slow = self._slow

        self._fast = sum(self._fast_values[-5:]) / 5.0
        self._slow = sum(self._slow_values[-20:]) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        if not (previous_fast <= previous_slow and self._fast > self._slow):
            return

        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        self._try_enter(slice, close, end_time)

