        self._entry_price = None
        self._time_stop_submitted = False
        self._expiration_liquidated = False
        self._assignment_handled = False

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration {} strike {}".format(
                selected.Symbol, expiration_date, selected.Strike
            )
        )

