            self._exit_ticket = self.MarketOrder(
                symbol, -holding.Quantity
            )
            self._time_stop_submitted = True
            self.Debug("Time-stop liquidation submitted: {}".format(symbol))
            return

        if self._entry_price is None:
            return

        if symbol not in slice.OptionChains:
            return

        quote = None
        for contract in slice.OptionChains[symbol.Canonical]:
            if contract.Symbol == symbol:
                quote = contract
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.5 * self._entry_price:
            return

        self._cancel_open_exit()
        self._exit_ticket = self.MarketOrder(
            symbol, -holding.Quantity
        )
        self.Debug("Profit-target liquidation submitted: {}".format(symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self._entry_symbol, self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self._entry_symbol = None
                self._entry_price = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self._entry_symbol = None
                self._entry_price = None
                self._exit_ticket = None
                self._entry_ticket = None
                self._time_stop_submitted = False
                self._expiration_liquidated = False

    def _cancel_open_exit(self):
        if self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self._exit_ticket.Cancel("Replacing exit order")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            if not self._assignment_handled:
                self.Liquidate(self.spy, "Unexpected exercise or assignment")
                self._assignment_handled = True
                self.Debug(
                    "Unexpected SPY equity position liquidated: {}".format(
                        holding.Quantity
                    )
                )
        else:
            self._assignment_handled = False

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

