from datetime import datetime, timedelta, time


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, True, False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        option.SetFilter(lambda u: u.Strikes(-100, 100).Expiration(0, 365))
        self.option_symbol = option.Symbol

        self.fast_values = []
        self.slow_values = []

        self.current_bucket_end = None
        self.current_bucket_bars = []
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.time_stop_date = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        now = self.Time
        current_date = now.date()

        if self.entry_symbol is not None:
            expiry = self.entry_symbol.ID.Date.date()

            if current_date >= expiry:
                self._liquidate_option("expiration")
                self.expiration_block_date = current_date

            elif (
                current_date == self._previous_trading_day(expiry)
                and now.time() >= time(15, 45)
                and self.time_stop_date != current_date
            ):
                self._liquidate_option("time stop")
                self.time_stop_date = current_date

            else:
                self._check_profit_target(slice)

        if self.spy in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy])

        if (
            self.expiration_block_date != current_date
            and self.entry_symbol is None
            and self.entry_ticket is None
            and self.current_bucket_end is not None
        ):
            self._try_entry(slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.time() < time(9, 31) or local_time.time() > time(16, 0):
            return

        if local_time.time() <= time(9, 35):
            bucket_end = datetime.combine(local_time.date(), time(9, 35))
        else:
            minutes = int(
                (local_time - datetime.combine(local_time.date(), time(9, 35))).total_seconds()
                // 60
            )
            bucket_end = datetime.combine(
                local_time.date(),
                time(9, 35)
            ) + timedelta(minutes=((minutes // 5) + 1) * 5)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end

        if bucket_end != self.current_bucket_end:
            self._complete_bucket()
            self.current_bucket_bars = []
            self.current_bucket_end = bucket_end

        self.current_bucket_bars.append(minute_bar)

    def _complete_bucket(self):
        if self.current_bucket_end is None:
            return

        # Do not synthesize or forward-fill incomplete five-minute bars.
        if len(self.current_bucket_bars) != 5:
            return

        end_time = self.current_bucket_end.time()
        if end_time < time(9, 35) or end_time > time(16, 0):
            return

        close = self.current_bucket_bars[-1].Close
        self.fast_values.append(close)
        self.slow_values.append(close)

