            if current_date >= expiration:
                self.block_entries_date = current_date
                if self._option_quantity() != 0 and not self._has_open_exit_order():
                    self._submit_exit("expiration")
                return

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.EndTime
        current_date = bar_time.date()

        if not (time(9, 30) <= bar_time.time() <= time(16, 0)):
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        bucket = self.minute_bars.setdefault(bucket_start, {})
        bucket[bar_time] = minute_bar

        boundary = bucket_start + timedelta(minutes=5)
        if bar_time != boundary - timedelta(minutes=1):
            return

        if self.last_processed_bar_end == boundary:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(expected_time not in bucket for expected_time in expected_times):
            self.minute_bars.pop(bucket_start, None)
            self.last_processed_bar_end = boundary
            return

