        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1, tag="bullish crossover")
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _process_held_option(self, slice: Slice):
        if self.entry_price is None or self.held_symbol is None:
            return

        quantity = self._option_quantity()
        if quantity <= 0:
            return

        contract = slice.OptionChains.get(self.option_symbol)
        bid = None
        ask = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_symbol:
                    bid = item.BidPrice
                    ask = item.AskPrice
                    break

        if (
            bid is not None and ask is not None
            and bid > 0 and ask > 0
        ):
            midpoint = (float(bid) + float(ask)) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                if not self._has_open_exit_order():
                    self._submit_exit("profit target")
                return

        expiration = self.held_symbol.ID.Date.date()
        if (
            self.Time.weekday() < 5
            and self.Time.date() < expiration
            and (expiration - self.Time.date()).days <= 3
            and self.Time.time() >= time(15, 45)
        ):
            next_day = self.Time.date() + timedelta(days=1)
            if next_day == expiration or expiration - self.Time.date() == timedelta(days=1):
                if not self._has_open_exit_order():
                    self._submit_exit("time stop")

    def _submit_exit(self, reason: str):
        quantity = self._option_quantity()
        if quantity == 0 or self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            self.exit_ticket.Cancel("replaced by liquidation order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: " + str(self.held_symbol)
                    + " at " + str(self.entry_price)
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status.IsOpen()
        )

    def _has_open_exit_order(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status.IsOpen()
        )

    def _option_quantity(self):
        if self.held_symbol is None:
            return 0
        return int(self.Portfolio[self.held_symbol].Quantity)

    def _liquidate_unexpected_spy_position(self):
        spy_quantity = int(self.Portfolio[self.spy_symbol].Quantity)
        if spy_quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment detected; "
                "liquidating equity position."
            )
            self.MarketOrder(
                self.spy_symbol,
                -spy_quantity,
                tag="unexpected exercise or assignment"
            )

